76	func (s *APIV1Service) BatchGetInstanceSettings(ctx context.Context, request *v1pb.BatchGetInstanceSettingsRequest) (*v1pb.BatchGetInstanceSettingsResponse, error) {
77		if len(request.Names) > maxBatchGetInstanceSettings {
78			return nil, status.Errorf(codes.InvalidArgument, "too many instance setting names (max %d)", maxBatchGetInstanceSettings)
79		}
80	
81		caller := &instanceSettingCaller{}
82		settings := make([]*v1pb.InstanceSetting, 0, len(request.Names))
83		for _, name := range request.Names {
