100		instanceSettingKey := storepb.InstanceSettingKey(storepb.InstanceSettingKey_value[instanceSettingKeyString])
101		// Get instance setting from store with default value.
102		var instanceSetting *storepb.InstanceSetting
103		switch instanceSettingKey {
104		case storepb.InstanceSettingKey_BASIC:
105			var setting *storepb.InstanceBasicSetting
106			setting, err = s.Store.GetInstanceBasicSetting(ctx)
107			instanceSetting = &storepb.InstanceSetting{Key: instanceSettingKey, Value: &storepb.InstanceSetting_BasicSetting{BasicSetting: setting}}
108		case storepb.InstanceSettingKey_GENERAL:
109			var setting *storepb.InstanceGeneralSetting
110			setting, err = s.Store.GetInstanceGeneralSetting(ctx)
111			instanceSetting = &storepb.InstanceSetting{Key: instanceSettingKey, Value: &storepb.InstanceSetting_GeneralSetting{GeneralSetting: setting}}
112		case storepb.InstanceSettingKey_MEMO_RELATED:
113			var setting *storepb.InstanceMemoRelatedSetting
114			setting, err = s.Store.GetInstanceMemoRelatedSetting(ctx)
115			instanceSetting = &storepb.InstanceSetting{Key: instanceSettingKey, Value: &storepb.InstanceSetting_MemoRelatedSetting{MemoRelatedSetting: setting}}
116		case storepb.InstanceSettingKey_STORAGE:
117			var setting *storepb.InstanceStorageSetting
118			setting, err = s.Store.GetInstanceStorageSetting(ctx)
119			instanceSetting = &storepb.InstanceSetting{Key: instanceSettingKey, Value: &storepb.InstanceSetting_StorageSetting{StorageSetting: setting}}
120		case storepb.InstanceSettingKey_TAGS:
121			var setting *storepb.InstanceTagsSetting
122			setting, err = s.Store.GetInstanceTagsSetting(ctx)
123			instanceSetting = &storepb.InstanceSetting{Key: instanceSettingKey, Value: &storepb.InstanceSetting_TagsSetting{TagsSetting: setting}}
124		case storepb.InstanceSettingKey_NOTIFICATION:
125			var setting *storepb.InstanceNotificationSetting
126			setting, err = s.Store.GetInstanceNotificationSetting(ctx)
127			instanceSetting = &storepb.InstanceSetting{Key: instanceSettingKey, Value: &storepb.InstanceSetting_NotificationSetting{NotificationSetting: setting}}
128		case storepb.InstanceSettingKey_AI:
129			var setting *storepb.InstanceAISetting
130			setting, err = s.Store.GetInstanceAISetting(ctx)
131			instanceSetting = &storepb.InstanceSetting{Key: instanceSettingKey, Value: &storepb.InstanceSetting_AiSetting{AiSetting: setting}}
132		default:
133			return nil, status.Errorf(codes.InvalidArgument, "unsupported instance setting key: %v", instanceSettingKey)
134		}
135		if err != nil {
136			return nil, status.Errorf(codes.Internal, "failed to get instance setting: %v", err)
137		}
138	
139		// Storage and notification settings contain credentials; restrict to admins only.
140		if instanceSetting.Key == storepb.InstanceSettingKey_STORAGE ||
141			instanceSetting.Key == storepb.InstanceSettingKey_NOTIFICATION {
142			user, err := caller.currentUser(ctx, s)
143			if err != nil {
144				return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
145			}
146			if user == nil {
147				return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
148			}
149			if user.Role != store.RoleAdmin {
150				return nil, status.Errorf(codes.PermissionDenied, "permission denied")
151			}
152		}
153		isAdminCaller := false
154		if instanceSetting.Key == storepb.InstanceSettingKey_AI {
155			user, err := caller.currentUser(ctx, s)
156			if err != nil {
157				return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
158			}
159			if user == nil {
160				return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
161			}
162			isAdminCaller = user.Role == store.RoleAdmin
163		}
164	
165		result := convertInstanceSettingFromStore(instanceSetting)
166		if instanceSetting.Key == storepb.InstanceSettingKey_AI && !isAdminCaller {
167			// Non-admin callers only need transcription.provider_id to gate the
168			// editor's Transcribe button. Model / language / prompt are
169			// admin-entered defaults that may contain proprietary glossary terms,
170			// so they are redacted from non-admin responses.
171			if ai := result.GetAiSetting(); ai != nil && ai.Transcription != nil {
172				ai.Transcription.Model = ""
173				ai.Transcription.Language = ""
174				ai.Transcription.Prompt = ""
175			}
176		}
177		return result, nil
178	}
