332	func (s *APIV1Service) GetInstanceAdmin(ctx context.Context) (*v1pb.User, error) {
333		adminUserType := store.RoleAdmin
334		user, err := s.Store.GetUser(ctx, &store.FindUser{
335			Role: &adminUserType,
336		})
337		if err != nil {
338			return nil, errors.Wrapf(err, "failed to find admin")
339		}
340		if user == nil {
341			return nil, nil
342		}
343	
344		currentUser, _ := s.fetchCurrentUser(ctx)
345		return convertUserFromStore(user, currentUser), nil
346	}
