16	func GetImage(urlStr string) (*Image, error) {
17		if _, err := url.Parse(urlStr); err != nil {
18			return nil, err
19		}
20	
21		response, err := http.Get(urlStr)
22		if err != nil {
23			return nil, err
24		}
