34	
35		bodyBytes, err := io.ReadAll(response.Body)
36		if err != nil {
37			return nil, err
38		}
39	
40		image := &Image{
41			Blob:      bodyBytes,
42			Mediatype: mediatype,
43		}
44		return image, nil
