1	// Package openai implements stt.Transcriber against the OpenAI
2	// /audio/transcriptions endpoint (and any compatible third-party endpoint
3	// such as Groq Whisper, faster-whisper self-hosted, or Azure Whisper).
4	package openai
5	
6	import (
7		"context"
8		"mime"
9		"net/url"
10		"strings"
11	
12		openaisdk "github.com/openai/openai-go/v3"
13		openaioption "github.com/openai/openai-go/v3/option"
14		"github.com/pkg/errors"
15	
16		"github.com/usememos/memos/internal/ai"
17		"github.com/usememos/memos/internal/ai/stt"
18	)
19	
20	const defaultEndpoint = "https://api.openai.com/v1"
21	
22	// Transcriber implements stt.Transcriber for OpenAI-compatible STT endpoints.
23	type Transcriber struct {
24		client openaisdk.Client
25	}
26	
27	// New constructs a Transcriber from a provider config.
28	func New(cfg ai.ProviderConfig, options stt.Options) (*Transcriber, error) {
29		endpoint, err := normalizeEndpoint(cfg.Endpoint)
30		if err != nil {
31			return nil, err
32		}
33		if cfg.APIKey == "" {
34			return nil, errors.New("OpenAI API key is required")
35		}
36		return &Transcriber{
37			client: openaisdk.NewClient(
38				openaioption.WithAPIKey(cfg.APIKey),
39				openaioption.WithBaseURL(endpoint),
40				openaioption.WithHTTPClient(options.HTTPClient),
41			),
42		}, nil
43	}
44	
45	// Transcribe sends the audio to /audio/transcriptions.
46	func (t *Transcriber) Transcribe(ctx context.Context, req stt.Request) (*stt.Response, error) {
47		if strings.TrimSpace(req.Model) == "" {
48			return nil, errors.New("model is required")
49		}
50		if req.Audio == nil {
51			return nil, errors.New("audio is required")
52		}
53	
54		filename, contentType, err := normalizeAudioMetadata(req)
55		if err != nil {
56			return nil, err
57		}
58	
59		params := openaisdk.AudioTranscriptionNewParams{
60			File:           openaisdk.File(req.Audio, filename, contentType),
61			Model:          openaisdk.AudioModel(req.Model),
62			ResponseFormat: openaisdk.AudioResponseFormatJSON,
63		}
64		if req.Prompt != "" {
65			params.Prompt = openaisdk.String(req.Prompt)
66		}
67		if req.Language != "" {
68			params.Language = openaisdk.String(req.Language)
69		}
70	
71		resp, err := t.client.Audio.Transcriptions.New(ctx, params)
72		if err != nil {
73			return nil, errors.Wrap(err, "failed to send OpenAI transcription request")
74		}
75		return &stt.Response{
76			Text:     resp.Text,
77			Language: resp.Language,
78		}, nil
79	}
80	
81	func normalizeEndpoint(endpoint string) (string, error) {
82		endpoint = strings.TrimSpace(endpoint)
83		if endpoint == "" {
84			endpoint = defaultEndpoint
85		}
86		if _, err := url.ParseRequestURI(endpoint); err != nil {
87			return "", errors.Wrap(err, "invalid OpenAI endpoint")
88		}
89		return strings.TrimRight(endpoint, "/"), nil
90	}
91	
92	func normalizeAudioMetadata(req stt.Request) (string, string, error) {
93		filename := strings.TrimSpace(req.Filename)
94		if filename == "" {
95			filename = "audio"
96		}
97		contentType := strings.TrimSpace(req.ContentType)
98		if contentType == "" {
99			contentType = "application/octet-stream"
100		} else {
101			mediaType, _, err := mime.ParseMediaType(contentType)
102			if err != nil {
103				return "", "", errors.Wrap(err, "invalid audio content type")
104			}
105			contentType = mediaType
106		}
107		return sanitizeFilename(filename), contentType, nil
108	}
109	
110	func sanitizeFilename(filename string) string {
111		filename = strings.NewReplacer("\r", "_", "\n", "_").Replace(filename)
112		if strings.TrimSpace(filename) == "" {
113			return "audio"
114		}
115		return filename
116	}
